   180	\subsection*{Derivation bridges}
   181	
   182	\begin{lemma}[Adiabatic invariant along a path]
   183	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:adiabatic_invariant_along_path}
   184	\lean{IPhO2026_3_B_2.adiabatic_invariant_along_path}
   185	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_B_2:ParamagneticTorusLaws, def:IPhO2026Problems_problem_IPhO_2026_3_B_2:IsAdiabaticPath, def:IPhO2026Problems_problem_IPhO_2026_3_B_2:adiabaticInvariant}
   186	Under the governing laws and the adiabatic first-law balance, any two states
   187	of one adiabatic path share the same value of $T^2\,(\lambda + \mu_0 K H^2)$.
   188	This is the carrier of the integration step
   189	$dT/T = -(\mu_0 K/\lambda)\,H\,dH$.
   190	Its derivability rests on the path-differentiability fields of the laws:
   191	off a differentiable path the first-law balance is vacuous (both
   192	$\mathrm{d}/\mathrm{d}t$ read as junk $0$) and the claim is false --- the
   193	Review countermodel class of iter-011 --- so the regularity premise is
   194	load-bearing, not cosmetic.
   195	\end{lemma}
   196	\begin{proof}
   197	Differentiate the equation of state along the differentiable path
   198	(product rule, legitimate by the \texttt{temp\_differentiable} and
   199	\texttt{mag\_differentiable} fields): $V\,(T\,\dot M + M\,\dot T) = nK\,\dot H$.
   200	The work rate is $w = \mu_0 V H\,\dot M$; substituting
   201	$V\,\dot M = nK\,\dot H/T - V M\,\dot T/T$ (from the differentiated EOS) into
   202	the first-law balance $C_M\,\dot T = -w$ with $C_M = n\lambda/T^2$ and
   203	$M = nKH/(TV)$ gives
   204	$(n\lambda/T^2)\,\dot T = -\mu_0 H(nK\,\dot H/T - nKH\,\dot T/T^2)$.
   205	Cancelling $n > 0$ and multiplying by $T^2$:
   206	$(\lambda + \mu_0 K H^2)\,\dot T + \mu_0 K T H\,\dot H = 0$, equivalently
   207	$\dot T/T = -(\mu_0 K/\lambda)\,H\,\dot H$.  Hence the derivative of
   208	$t \mapsto T(t)^2(\lambda + \mu_0 K H(t)^2)$ vanishes at every parameter by
   209	the product rule, using only the proved positivity
   210	$\lambda + \mu_0 K H^2 > 0$ of
   211	\cref{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:lam_add_mu0_K_sq_pos};
   212	an everywhere differentiable function with identically vanishing derivative
   213	is constant (mean value theorem), so the invariant agrees at $t_1$ and $t_2$.
   214	\end{proof}
   215	
   216	\begin{lemma}[Endpoint relation]
   217	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:endpoint_relation}
   218	\lean{IPhO2026_3_B_2.endpoint_relation}
   219	\uses{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:adiabatic_invariant_along_path, def:IPhO2026Problems_problem_IPhO_2026_3_B_2:AdiabaticEndpoints}
   220	Specialized to the recorded endpoints $(H_i, T_i)$ and $(H_f, T_f)$ of the
   221	ramp, the conserved invariant gives
   222	$T_f^2\,(\lambda + \mu_0 K H_f^2) = T_i^2\,(\lambda + \mu_0 K H_i^2)$.
   223	\end{lemma}
   224	\begin{proof}
   225	Apply
   226	\cref{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:adiabatic_invariant_along_path}
   227	to any two path-parameter values realizing the initial state $(H_i, T_i)$
   228	(supplied by the endpoint data) and the witnessed final state $(H_f, T_f)$,
   229	then unfold the invariant at both points.
   230	\end{proof}
   231	
   232	\begin{lemma}[Positivity of the bracket]
   233	\label{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:lam_add_mu0_K_sq_pos}
   234	\lean{IPhO2026_3_B_2.lam_add_mu0_K_sq_pos}
   235	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_B_2:TorusParameters}
   236	For the positive parameters of the problem and any signed field $H$,
   237	$\lambda + \mu_0 K H^2 > 0$; this certifies that the square root and the
   238	quotient in the final answer are well-defined for either ramp direction.
   239	\end{lemma}
   240	\begin{proof}
   241	$H^2 \ge 0$ and $\mu_0, K > 0$ make $\mu_0 K H^2 \ge 0$; adding $\lambda > 0$
   242	forces the sum to be strictly positive.
   243	\end{proof}
