   245	\subsection*{Target value theorem}
   246	
   247	\begin{theorem}[Adiabatic temperature change]
   248	\label{thm:IPhO2026Problems_problem_IPhO_2026_3_B_2:adiabatic_temperature_change}
   249	\lean{IPhO2026_3_B_2.adiabatic_temperature_change}
   250	\uses{def:IPhO2026Problems_problem_IPhO_2026_3_B_2:ParamagneticTorusLaws, def:IPhO2026Problems_problem_IPhO_2026_3_B_2:IsAdiabaticPath, def:IPhO2026Problems_problem_IPhO_2026_3_B_2:AdiabaticEndpoints, lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:endpoint_relation, lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:lam_add_mu0_K_sq_pos}
   251	\textbf{(Target, T3-B.2.)}  For an adiabatic change $H_i \to H_f$ of the
   252	paramagnetic torus starting at temperature $T_i$, with final temperature
   253	$T_f > 0$, the temperature change is
   254	\[
   255	\Delta T = T_f - T_i
   256	  = T_i\,\biggl(\sqrt{\frac{\lambda + \mu_0 K H_f^2}
   257	                          {\lambda + \mu_0 K H_i^2}} - 1\biggr),
   258	\]
   259	the recorded official answer of part B.2.  The relation is conclusion-side
   260	only: the hypotheses carry the governing laws, the adiabatic balance, the
   261	positive parameters, and the endpoint and regularity data $H_i \ge 0$,
   262	$T_i > 0$, $T_f > 0$ --- the square-root expression appears in no premise.
   263	\end{theorem}
   264	\begin{proof}
   265	From the endpoint relation of
   266	\cref{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:endpoint_relation},
   267	$T_f^2 = T_i^2\,(\lambda + \mu_0 K H_f^2)/(\lambda + \mu_0 K H_i^2)$; the
   268	denominator is strictly positive by
   269	\cref{lem:IPhO2026Problems_problem_IPhO_2026_3_B_2:lam_add_mu0_K_sq_pos}, so
   270	taking square roots with $T_i > 0$ and the assumed $T_f > 0$ gives
   271	$T_f = T_i\,\sqrt{(\lambda + \mu_0 K H_f^2)/(\lambda + \mu_0 K H_i^2)}$,
   272	hence $T_f - T_i$ has the displayed form.
   273	\end{proof}

