   470	\begin{lemma}[Asymptote factor certificate]
   471	\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:asymptote_factor_certificate}
   472	\lean{IPhO2026.Problem1.B2.asymptote_factor_certificate}
   473	The hyperbola $\varepsilon^2 = 67/4$ makes the scattering asymptote factor
   474	$1/\sqrt{\varepsilon^2 - 1} = 1/\sqrt{67/4 - 1} = 2/\sqrt{63}$.
   475	\end{lemma}
   476	\begin{proof}
   477	$67/4 - 1 = 63/4 = (\sqrt{63}/2)^2$ using $\sqrt{63}^{\,2} = 63$; taking
   478	the positive square root gives $\sqrt{63/4} = \sqrt{63}/2$, and inverting
   479	yields $2/\sqrt{63}$.  Pure algebra up to that square-root identity.
   480	\end{proof}
